css:
@font-face{font-family:'IT';font-weight:900;unicode-range:U+0370-03FF;src:url(node_modules/@fontsource/inter-tight/files/inter-tight-greek-900-normal.woff2)}
@font-face{font-family:'IN';font-weight:500;unicode-range:U+0370-03FF;src:url(node_modules/@fontsource/inter/files/inter-greek-500-normal.woff2)}
@font-face{font-family:'IN';font-weight:700;unicode-range:U+0370-03FF;src:url(node_modules/@fontsource/inter/files/inter-greek-700-normal.woff2)}

@font-face{font-family:'IT';font-weight:900;src:url(node_modules/@fontsource/inter-tight/files/inter-tight-latin-900-normal.woff2)}
@font-face{font-family:'IT';font-weight:800;src:url(node_modules/@fontsource/inter-tight/files/inter-tight-latin-800-normal.woff2)}
@font-face{font-family:'IN';font-weight:500;src:url(node_modules/@fontsource/inter/files/inter-latin-500-normal.woff2)}
@font-face{font-family:'IN';font-weight:700;src:url(node_modules/@fontsource/inter/files/inter-latin-700-normal.woff2)}
.card{background:#FFFFFF;color:#111;font-family:'IN';
 background-image:linear-gradient(#EDEDED 2px,transparent 2px),linear-gradient(90deg,#EDEDED 2px,transparent 2px);background-size:135px 135px;}
.card-1{background:#FFD400;background-image:none}
.safe{display:flex;flex-direction:column}
.hd{display:flex;justify-content:space-between;align-items:center;border-bottom:10px solid #111;padding-bottom:22px;margin-bottom:60px;font:700 36px 'IN';letter-spacing:3px;text-transform:uppercase}
.tag{align-self:flex-start;background:#FFD400;color:#111;font:700 46px 'IN';padding:12px 22px;margin-bottom:44px;letter-spacing:1px}
h1{font:900 172px/.92 'IT';letter-spacing:-5px;margin:0}
h2{font:900 146px/.95 'IT';letter-spacing:-4px;margin:0 0 40px}
.big{font:900 250px/.9 'IT';letter-spacing:-7px;margin:0 0 30px}
.ln{font:500 60px/1.28 'IN';margin:0 0 40px;padding-left:34px;border-left:12px solid #111;max-width:820px}
.ln b{font-weight:700;background:#FFD400;padding:0 8px}
.kick{font:700 44px 'IN';margin:0 0 50px;text-transform:uppercase;letter-spacing:3px}
.sub{font:500 56px/1.25 'IN';margin-top:60px;max-width:800px}
.row{display:flex;gap:34px;align-items:flex-start;border-top:8px solid #111;padding:44px 0;}
.row b{font:900 116px/1 'IT';min-width:330px;letter-spacing:-3px}
.row span{font:500 56px/1.28 'IN'}
.blk{width:190px;height:190px;background:#111;margin-top:70px}
.handle{font:700 66px 'IN';margin-top:50px}
.small{font:500 52px 'IN';margin-top:30px}
